// Sangrah branding for generated files (PDFs).
// The app icon (Resources/Assets.xcassets/AppIcon.appiconset/AppIcon.png) at 96 px,
// inlined so the function needs no storage read. Regenerate with:
//   sips -Z 96 AppIcon.png --out icon96.png && base64 -i icon96.png

export const BRAND_NAME = 'Sangrah';

/** Icon palette navy (#1C2140), for the wordmark */
export const BRAND_NAVY = { r: 0x1c / 255, g: 0x21 / 255, b: 0x40 / 255 };

export const BRAND_ICON_PNG_BASE64 =
  '';

export function brandIconBytes(): Uint8Array {
  return Uint8Array.from(atob(BRAND_ICON_PNG_BASE64), (c) => c.charCodeAt(0));
}
